const now = new Date(new Date().toLocaleString("en-US", {timeZone: "Asia/Seoul"}));
const yyyy = String(now.getFullYear());
const mm = String(now.getMonth() + 1).padStart(2, "0");
const dd = String(now.getDate()).padStart(2, "0");
const ymd = yyyy + mm + dd;
const dateLabel = `${yyyy}-${mm}-${dd}`;
return [{ json: { yyyy, mm, dd, ymd, dateLabel } }];

// 3protv기사_*.md(원문 기사 덤프, 30~50KB)는 제외한다 — 이미 요약된
// 오늘/정오/야간/ETF 리포트만 다이제스트 재료로 쓴다.
const items = $input.all();
const reports = [];
const indexMap = new Map();   // 지수명 → "종가 아이콘 ▲/▼N%"
let flowBlock = '';           // 수급 요약(개인/외국인/기관) 원문 블록

const INDEX_NAMES = ['다우존스', 'S&P500', '나스닥', 'KOSPI', '코스피', 'KOSDAQ', '코스닥'];
// report.py _quote_line(): "• 이름: 12,345.6 📈 ▲1.23%" 형식
const QUOTE_RE = /^•\s*([^:：\n]+?)[:：]\s*[\d,.]+\s*[^\n]*?[▲▼]\s*[\d.]+%/gm;
// report.py _flow_lines(): "• 수급 요약 (MM/DD 순매수, 억원)" 헤더 + "  · 개인: ..." 줄들
const FLOW_RE = /•\s*수급\s*요약[^\n]*\n(?:\s*·[^\n]*\n?)+/;

for (const item of items) {
  const bin = item.binary && item.binary.data;
  if (!bin) continue;
  const fileName = bin.fileName || '';
  if (fileName.startsWith('3protv기사')) continue;
  const buf = Buffer.from(bin.data, 'base64');
  const text = buf.toString('utf-8');

  // 지수·수급 줄은 잘리기 전 원문 전체에서 정규식으로 뽑는다 — 리포트 뒷부분에
  // 있어도(수급 섹션이 특히 그렇다) 4000자 truncation과 무관하게 항상 잡힌다.
  // LLM이 "찾아서 정리"하게 하는 대신 코드로 직접 추출 — 금액·등락률은
  // 사람 손 없이 정확해야 하는 값이라 Gemini에 맡기지 않는다(2026-08-13 확정).
  let m;
  QUOTE_RE.lastIndex = 0;
  while ((m = QUOTE_RE.exec(text)) !== null) {
    const name = m[1].trim();
    const hit = INDEX_NAMES.find(n => name.includes(n));
    if (hit) indexMap.set(hit, m[0].replace(/^•\s*/, ''));
  }
  if (!flowBlock) {
    const fm = text.match(FLOW_RE);
    if (fm) flowBlock = fm[0].trim();
  }

  // Gemini에 넘길 본문은 여전히 4000자로 자른다 (종목 언급·흐름 요약용 — 이
  // 두 가지는 위치가 안 정해져 있어 코드 추출이 안 되고 LLM이 필요하다)
  reports.push({ fileName, text: text.slice(0, 4000) });
}

if (reports.length === 0) {
  return [{ json: { skip: true } }];
}

const { ymd, dateLabel } = $('오늘 경로 계산').first().json;
const body = reports.map(r => `### ${r.fileName}\n${r.text}`).join('\n\n');
const indexLines = [...indexMap.entries()].map(([name, line]) => `${name}: ${line}`);
const indexSectionText = indexLines.length ? indexLines.join('\n') : '데이터 없음';
const flowSectionText = flowBlock || '데이터 없음';

const prompt = `아래는 ${dateLabel} 삼프로TV 관련 리포트 ${reports.length}건이다. `
  + `다음만 처리해줘 (지수·수급은 이미 코드로 따로 추출했으니 다루지 않는다).\n\n`
  + `1) 📈 리포트 언급 종목 마감 (전일 대비)\n`
  + `리포트 안에 "• 종목명: 종가 아이콘 ▲또는▼등락률%" 형식의 시세 줄들이 있다. `
  + `지수(다우존스/S&P500/나스닥/KOSPI/KOSDAQ)는 제외하고 개별 종목만 찾아 `
  + `"종목명: 종가 (▲/▼N.NN%)" 한 줄씩 나열해줘. 언급된 종목이 없으면 "언급 종목 없음"이라고 써줘. `
  + `숫자는 리포트에 적힌 값만 그대로 옮겨줘.\n\n`
  + `2) 📋 오늘 흐름 요약\n`
  + `핵심만 3~5줄 불릿으로 종합 요약해줘. 리포트별로 나열하지 말고 하루 흐름을 하나로 엮어서.\n\n`
  + `공통 규칙: 매매 시점·수량 등 개인화된 투자 자문은 하지 말고 정보 전달만 해줘.\n\n${body}`;

return [{ json: {
  skip: false, prompt, ymd, dateLabel, count: reports.length,
  fileNames: reports.map(r => r.fileName),
  indexSectionText, flowSectionText
} }];

// Gemini 실패(429 할당량 소진 등)도 조용히 죽지 않고 텔레그램으로 알린다
// (2026-07-27 GH_PAT 침묵 실패 사고 재발 방지 원칙과 동일선상)
const res = $json;
const built = $('다이제스트용 본문 구성').first().json;
const { yyyy, mm } = $('오늘 경로 계산').first().json;
const candidate = res.candidates && res.candidates[0];
const text = candidate && candidate.content && candidate.content.parts && candidate.content.parts[0]
  ? candidate.content.parts[0].text.trim()
  : null;

// 지수·수급은 Gemini와 무관하게 코드로 이미 추출돼 있다 — Gemini가 실패해도
// 이 두 섹션은 그대로 살아서 나간다(2026-08-13: 숫자 데이터는 요약 실패와
// 별개로 최대한 전달하자는 원칙).
const dataBlock = `📊 주요 지수 (전일 대비)\n${built.indexSectionText}\n\n`
  + `💰 수급 동향 (개인/외국인/기관, 전일대비 · 억원)\n${built.flowSectionText}\n\n`;

let message;
if (text) {
  message = `📋 3프로TV 오늘의 종합 다이제스트 (${built.dateLabel})\n\n${dataBlock}${text}\n\n`
    + `— 오늘 발행된 리포트 ${built.count}건 종합 (원문: 옵시디안 3protv/${yyyy}/${mm}/)`;
} else {
  message = `⚠️ 오늘(${built.dateLabel}) 다이제스트 요약 생성 실패 (Gemini 응답 이상 — 할당량 소진 가능성)\n`
    + `개별 리포트 ${built.count}건은 정상 저장됐습니다 — 옵시디안에서 직접 확인해주세요.\n\n${dataBlock}`;
}

// 텔레그램 chat_id는 콤마로 합쳐서 한 번에 못 보낸다(2026-08-13 사고 —
// Bot API는 요청 1회당 chat_id 1개만 받는다). 방마다 아이템을 나눠 반환하면
// 다음 노드(텔레그램 발송)가 아이템 수만큼 자동으로 반복 호출된다.
const chatIds = ["<N8N_TELEGRAM_CHAT_ID_1>", "<N8N_TELEGRAM_CHAT_ID_2>"];
return chatIds.map(id => ({ json: { text: message, chat_id: id } }));
